import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        // Read stdin as raw bytes: lines may contain spaces, tabs and UTF-8.
        byte[] data = System.in.readAllBytes();
        int pos = 0, end = pos;
        while (data[end] != '\n') end++;
        String[] header = new String(data, pos, end - pos, "US-ASCII").trim().split("\\s+");
        pos = end + 1;
        int count = Integer.parseInt(header[0]), keep = Integer.parseInt(header[1]);
        // Keep at most `keep` (start, length) records of the most recent lines.
        ArrayDeque<int[]> window = new ArrayDeque<>();
        for (int i = 0; i < count; i++) {
            end = pos;
            while (data[end] != '\n') end++;
            int length = Integer.parseInt(new String(data, pos, end - pos, "US-ASCII").trim());
            pos = end + 1;
            if (keep > 0) {
                window.addLast(new int[] {pos, length});
                if (window.size() > keep) window.pollFirst();
            }
            pos += length + 1;
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write((window.size() + "\n").getBytes("US-ASCII"));
        for (int[] w : window) {
            out.write((w[1] + "\n").getBytes("US-ASCII"));
            out.write(data, w[0], w[1]);
            out.write('\n');
        }
        System.out.write(out.toByteArray());
        System.out.flush();
    }
}

package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	// Read stdin as raw bytes: lines may contain spaces, tabs and UTF-8.
	data, _ = io.ReadAll(os.Stdin)
	line := func() string {
		end := pos + bytes.IndexByte(data[pos:], '\n')
		value := string(data[pos:end])
		pos = end + 1
		return strings.TrimSpace(value)
	}
	header := strings.Fields(line())
	count, _ := strconv.Atoi(header[0])
	keep, _ := strconv.Atoi(header[1])
	// Keep at most `keep` byte slices of the most recent lines.
	window := [][]byte{}
	for i := 0; i < count; i++ {
		length, _ := strconv.Atoi(line())
		if keep > 0 {
			window = append(window, data[pos:pos+length])
			if len(window) > keep {
				window = window[1:]
			}
		}
		pos += length + 1
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	fmt.Fprintf(w, "%d\n", len(window))
	for _, value := range window {
		fmt.Fprintf(w, "%d\n", len(value))
		w.Write(value)
		w.WriteByte('\n')
	}
}
